export function table(headers, rows, caption = '数据记录') {
  const thead = `<thead><tr>${headers.map(h => `<th scope="col">${h}</th>`).join('')}</tr></thead>`;
  const tbody = `<tbody>${rows.map((row, index) => `<tr data-record-row data-record-index="${index}" tabindex="0" aria-label="查看第 ${index + 1} 条记录详情">${row.map(cell => `<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody>`;
  return `<div class="cds-data-table-container"><table class="data-table" aria-label="${caption}">${thead}${tbody}</table></div>`;
}

src/components/tag.js.body:
export function tag(text, variant = 'gray', withDot = false) {
  const dot = withDot ? '<span class="dot"></span>' : '';
  return `<span class="tag tag-${variant}">${dot}${text}</span>`;
}

export function boolTag(value) {
  if (value === true) return tag('True', 'green');
  if (value === false) return tag('False', 'gray');
  return tag('Unknown', 'yellow');
}

export function statusTag(status) {
  const map = {
    scraped: ['已抓取', 'green'],
    pending: ['待处理', 'yellow'],
    skipped: ['跳过', 'red'],
  };
  const [text, variant] = map[status] || ['未知', 'gray'];
  return tag(text, variant, true);
}

src/components/toast.js.body:
let timer = null;
export function showToast(message) {
  const el = document.getElementById('toast');
  el.textContent = message;
  el.style.display = 'block';
  clearTimeout(timer);
  timer = setTimeout(() => { el.style.display = 'none'; }, 2500);
}

